export type ExtensionIntent = Extract<Intent, { kind: "CancelExtensionInstall" | "ChangeExtension" | "InstallExtension" | "ListExtensions" }>;

/** The members of `Intent` that derive from the core's `ImportWorkspace`. */
export type ImportWorkspace = Extract<Intent, { kind: "ApplyManualSetup" | "ImportReviewedSpaces" | "ImportSpaces" }>;

export function decodeImportWorkspace(r: WireReader): ImportWorkspace {
    const tag = r.tag();
    switch (tag) {
        case 24: return { kind: "ApplyManualSetup", value: decodeApplyManualSetup(r) };
        case 124: return { kind: "ImportReviewedSpaces", value: decodeImportReviewedSpaces(r) };
        case 125: return { kind: "ImportSpaces", value: decodeImportSpaces(r) };
        default: throw new WireError(`Intent tag ${tag} is not a ImportWorkspace.`);
    }
}

