/** The user-facing English texts a `Rejection` carries, by name. */
export function textsOfRejection(m: Rejection): Readonly<Partial<Record<"message", LocalizedText>>> {
    switch (m.kind) {
        case "AgentNotApproved": return textsOfAgentNotApproved(m.value);
        case "AgentSessionsFull": return textsOfAgentSessionsFull(m.value);
        case "AgentSpaceUnavailable": return textsOfAgentSpaceUnavailable(m.value);
        case "AgentTabStopped": return textsOfAgentTabStopped(m.value);
        case "AgentTabUnavailable": return textsOfAgentTabUnavailable(m.value);
        case "AgentsFull": return textsOfAgentsFull(m.value);
        case "AgentsOff": return textsOfAgentsOff(m.value);
        case "AgentsUnavailable": return textsOfAgentsUnavailable(m.value);
        case "ArchiveInvalid": return textsOfArchiveInvalid(m.value);
        case "ArchiveTooLarge": return textsOfArchiveTooLarge(m.value);
        case "BookmarksHaveNoLinks": return textsOfBookmarksHaveNoLinks(m.value);
        case "BookmarksOverLimits": return textsOfBookmarksOverLimits(m.value);
        case "BookmarksTooLarge": return textsOfBookmarksTooLarge(m.value);
        case "BookmarksUnrecognized": return textsOfBookmarksUnrecognized(m.value);
        case "CannotDeleteLastSpace": return textsOfCannotDeleteLastSpace(m.value);
        case "CannotMoveSplitAcrossSpaces": return textsOfCannotMoveSplitAcrossSpaces(m.value);
        case "CannotPinSplit": return textsOfCannotPinSplit(m.value);
        case "CurrentTabsOnly": return textsOfCurrentTabsOnly(m.value);
        case "DuplicateSearchEngineName": return textsOfDuplicateSearchEngineName(m.value);
        case "DuplicateSearchShortcut": return textsOfDuplicateSearchShortcut(m.value);
        case "ExtensionNotChangeable": return textsOfExtensionNotChangeable(m.value);
        case "FileUnreadable": return textsOfFileUnreadable(m.value);
        case "GuideSpaceLocked": return textsOfGuideSpaceLocked(m.value);
        case "IncompleteSplit": return textsOfIncompleteSplit(m.value);
        case "InvalidAgent": return textsOfInvalidAgent(m.value);
        case "InvalidImport": return textsOfInvalidImport(m.value);
        case "InvalidSearchShortcut": return textsOfInvalidSearchShortcut(m.value);
        case "InvalidSyncRecords": return textsOfInvalidSyncRecords(m.value);
        case "LegacyCloudStateUnreadable": return textsOfLegacyCloudStateUnreadable(m.value);
        case "NoIncludedSpaces": return textsOfNoIncludedSpaces(m.value);
        case "NoManualSetup": return textsOfNoManualSetup(m.value);
        case "NoSetup": return textsOfNoSetup(m.value);
        case "NotAnArchive": return textsOfNotAnArchive(m.value);
        case "PersistentWorkspaceRequired": return textsOfPersistentWorkspaceRequired(m.value);
        case "PinnedTabsDragAlone": return textsOfPinnedTabsDragAlone(m.value);
        case "PinnedTabsFull": return textsOfPinnedTabsFull(m.value);
        case "PinnedTabsStayPut": return textsOfPinnedTabsStayPut(m.value);
        case "PinsOneTabAtATime": return textsOfPinsOneTabAtATime(m.value);
        case "PrimaryCannotJoin": return textsOfPrimaryCannotJoin(m.value);
        case "PrimaryCannotSeparate": return textsOfPrimaryCannotSeparate(m.value);
        case "PrivateSpaceCannotLock": return textsOfPrivateSpaceCannotLock(m.value);
        case "PrivateSpaceCannotShare": return textsOfPrivateSpaceCannotShare(m.value);
        case "ProfileInUse": return textsOfProfileInUse(m.value);
        case "SaveFailed": return textsOfSaveFailed(m.value);
        case "SearchEngineLimitReached": return textsOfSearchEngineLimitReached(m.value);
        case "SelectionChanged": return textsOfSelectionChanged(m.value);
        case "SelectionHoldsFolders": return textsOfSelectionHoldsFolders(m.value);
        case "SessionEncrypted": return textsOfSessionEncrypted(m.value);
        case "SessionHasNoTabs": return textsOfSessionHasNoTabs(m.value);
        case "SessionOverLimits": return textsOfSessionOverLimits(m.value);
        case "SessionTooLarge": return textsOfSessionTooLarge(m.value);
        case "SessionUnrecognized": return textsOfSessionUnrecognized(m.value);
        case "SetupBusy": return textsOfSetupBusy(m.value);
        case "SitePermissionLimitReached": return textsOfSitePermissionLimitReached(m.value);
        case "SpaceAlreadyExists": return textsOfSpaceAlreadyExists(m.value);
        case "SpaceBeingDeleted": return textsOfSpaceBeingDeleted(m.value);
        case "SpaceDeletionUnderway": return textsOfSpaceDeletionUnderway(m.value);
        case "SpaceIsPrivate": return textsOfSpaceIsPrivate(m.value);
        case "SpaceLimitReached": return textsOfSpaceLimitReached(m.value);
        case "SpaceLocked": return textsOfSpaceLocked(m.value);
        case "SpaceProfileChanged": return textsOfSpaceProfileChanged(m.value);
        case "SplitLimitReached": return textsOfSplitLimitReached(m.value);
        case "SplitNeedsTwoTabs": return textsOfSplitNeedsTwoTabs(m.value);
        case "UnknownAgentSession": return textsOfUnknownAgentSession(m.value);
        case "UnknownCloudMerge": return textsOfUnknownCloudMerge(m.value);
        case "UnknownExtension": return textsOfUnknownExtension(m.value);
        case "UnsuitableDefaultSearch": return textsOfUnsuitableDefaultSearch(m.value);
        case "UnsupportedArchiveVersion": return textsOfUnsupportedArchiveVersion(m.value);
        case "WebPagesOnly": return textsOfWebPagesOnly(m.value);
        default: return {};
    }
}

